import json, collections, hashlib
from pathlib import Path
from fractions import Fraction as F
from decimal import Decimal as D
BASE=Path('/workspace/scratch/3bd8c10a8771/grade3_research')
connections=json.loads((BASE/'grade3_to_6_connections.json').read_text())
upper=json.loads((BASE/'upper_problem_types.json').read_text())
core=json.loads((BASE/'core_taxonomy.json').read_text())
content={n['id']:n for n in connections['nodes']}
original={t['id']:t for t in upper['types']}
details=[]

def typ(title, old, prompt, answer, solution, misconception, checks=()):
    return {'title':title,'originalTypeIds':old.split() if old else [],'example':{'prompt':prompt,'answer':answer,'solution':solution,'misconception':misconception,'authorship':'original'},'arithmeticChecks':[{'expression':x,'expected':str(y)} for x,y in checks]}

def add(parent,title,types,standards=None):
    n=content[parent]; index=1+sum(x['parentContentId']==parent for x in details)
    sid=n['sourceIds'][:]
    if n['officialGradeBand']=='3~4' and 'S2' not in sid:sid.append('S2')
    pub={'5-1':'UP-P51','5-2':'UP-P52','6-1':'UP-P61','6-2':'UP-P62'}.get(n['observedPlacement'])
    if pub:sid.append(pub)
    did=f'{parent}-SD{index:02d}'
    for i,t in enumerate(types,1):
        t.update(id=f'{did}-T{i:02d}',parentId=did,kind='problem-type',sourceIds=sid[:],evidenceStatus='proposed-original',standardIds=standards or n['standardIds'])
        t['reusedCoreTypeIds']=sorted(set(cid for oid in t['originalTypeIds'] for cid in original[oid].get('reusedCoreTypeIds',[])))
        t['originalSourceRefs']=[{'file':'upper_problem_types.json','typeId':oid,'sourceIds':original[oid]['sourceIds']} for oid in t['originalTypeIds']]
        t['alignmentNote']='확인한 교육과정 범위와 자료의 내용 구분을 참고해 연구자가 세분화한 유형이다. 예시 문항·정답·풀이는 새로 작성했으며 출판사 문항 인용이나 공식 유형 목록이 아니다.'
    details.append({'id':did,'parentContentId':parent,'kind':'detail-unit','title':title,'officialGradeBand':n['officialGradeBand'],'observedPlacement':n['observedPlacement'],'placementStatus':n['placementStatus'],'connectionRole':n['connectionRole'],'standardIds':standards or n['standardIds'],'sourceIds':sid,'evidenceStatus':'proposed-original','types':types})

